WITH filtered AS (SELECT *, UPPER(merchant) AS merchant_upper, TO_DATE(txn_time) AS txn_time_date FROM transactions WHERE merchant IS NOT NULL AND is_flagged) SELECT id, account_id, amount, txn_time_date, MIN(amount) OVER (PARTITION BY merchant, account_id ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_amount, COUNT(amount) OVER (PARTITION BY merchant, account_id ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_amount, SUM(amount) OVER (PARTITION BY merchant, account_id ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_amount FROM filtered;
